// Get the tree from HTTP response
const tree = $input.first().json.tree;

// Repo info
const repoOwner = $('Edit Fields').first().json.repo_owner;
const repoName = $('Edit Fields').first().json.repo_name;
const branch = $('Edit Fields').first().json.branch;

// Allowed file extensions (NO CSV)
const allowedExtensions = [
  'py', 'js', 'ts', 'tsx', 'jsx',
  'md', 'json', 'yaml', 'yml',
  'css', 'html', 'txt', 'sh', 'env',
  'ipynb'
];

// Paths to exclude
const excludedPaths = [
  '__pycache__/',
  '.pyc',
  'node_modules/',
  'dist/',
  'build/',
  '.git/',
  'venv/',
  '.next/',
  'coverage/',
  '.github/',
  '.idea/',
  '.vscode/'
];

// Filenames to exclude
const excludedFiles = [
  '__init__.py'
];

// Size limit
const MAX_FILE_SIZE = 1_000_000;   // 1MB

// Filter files
const filteredFiles = tree
  .filter(item => item.type === 'blob')
  .filter(item => item.size > 0)                     // 🚫 remove zero-byte files
  .filter(item => {
    const ext = item.path.split('.').pop().toLowerCase();
    return allowedExtensions.includes(ext);
  })
  .filter(item => {
    return !excludedPaths.some(excluded =>
      item.path.includes(excluded)
    );
  })
  .filter(item => {
    const filename = item.path.split('/').pop().toLowerCase();
    return !excludedFiles.includes(filename);
  })
  .filter(item => item.size <= MAX_FILE_SIZE);

// Prepare output
const output = filteredFiles.map(file => {
  const ext = file.path.split('.').pop().toLowerCase();

  return {
    json: {
      file_path: file.path,
      file_size: file.size,
      repo_owner: repoOwner,
      repo_name: repoName,
      branch: branch,
      file_extension: ext,
      sha: file.sha
    }
  };
});

console.log(
  `✅ Indexed ${filteredFiles.length} files from ${repoOwner}/${repoName}@${branch}`
);

return output;

// Decode base64 content to readable UTF-8 text
const content = Buffer.from($json.content || '', 'base64').toString('utf-8');

// Repo info
const repo_name = $('Edit Fields').first().json.repo_name;
const repo_owner = $('Edit Fields').first().json.repo_owner;
const branch = $('Edit Fields').first().json.branch;

// File path (GitHub sometimes sends `path` or `name`)
const filePath = $json.path || 'unknown';

// Get raw file extension
const rawExtension = (filePath.split('.').pop() || '').toLowerCase();

// Map file extensions to Text Splitter language codes
const extensionMap = {
  py: 'python',
  md: 'markdown',
  js: 'js',
  ts: 'js',
  jsx: 'js',
  tsx: 'js',
  java: 'java',
  cpp: 'cpp',
  cc: 'cpp',
  cxx: 'cpp',
  go: 'go',
  php: 'php',
  rb: 'ruby',
  rs: 'rust',
  scala: 'scala',
  swift: 'swift',
  tex: 'latex',
  rst: 'rst',
  proto: 'proto',
  html: 'html'
};

// Get the correct splitter language (or empty for generic)
const splitterCode = extensionMap[rawExtension] || '';

// Return in LangChain-compatible format
return {
  json: {
    pageContent: content,
    file_extension: splitterCode,   // Used by Text Splitter
    metadata: {
      file_path: filePath,
      repository: `${repo_owner}/${repo_name}`,   // FIXED
      branch: branch,
      file_type: rawExtension,
      file_size: $json.size || 0,
      indexed_at: new Date().toISOString(),
      sha: $json.sha || null
    }
  }
};

const input = $input.first().json.body.github_url;
const branch = $input.first().json.body.branch

if (!input) {
  throw new Error("github_url is missing");
}

let url = input.trim();

// Remove protocol
url = url.replace(/^https?:\/\//, "");

// Remove query string or hash
url = url.split("?")[0].split("#")[0];

// Now split by /
const parts = url.split("/").filter(p => p.length > 0);

// Handle raw.githubusercontent.com
// raw.githubusercontent.com/owner/repo/branch/file
if (parts[0] === "raw.githubusercontent.com") {
  if (parts.length < 3) {
    throw new Error("Invalid raw GitHub URL");
  }

  return {
    json: {
      repo_owner: parts[1],
      repo_name: parts[2],
      full_repo: `${parts[1]}/${parts[2]}`
    }
  };
}

// Handle github.com
// github.com/owner/repo/...
if (parts[0] === "github.com") {
  if (parts.length < 3) {
    throw new Error("Invalid GitHub repository URL");
  }

  const repo_owner = parts[1];
  const repo_name = parts[2].replace(/\.git$/, "");

  return {
    json: {
      repo_owner,
      repo_name,
      full_repo: `${repo_owner}/${repo_name}`,
      branch_name : branch
    }
  };
}

throw new Error("Not a GitHub URL");
